  "test": "import request from 'supertest';
import { beforeEach, describe, expect, it } from 'vitest';
import { createApp } from '../src/app';
import { createDb, type DB } from '../src/db';

let db: DB;
let app: ReturnType<typeof createApp>;

beforeEach(() => {
  db = createDb();
  app = createApp(db);
});

describe('seguridad de errores', () => {
  it('no expone el stack trace ni el mensaje interno en errores 500', async () => {
    // Agregamos una ruta temporal que lanza un error para probar el middleware global
    app.get('/trigger-error', (_req, _res, next) => {
      next(new Error('Internal database failure with secret path /var/www/app'));
    });

    const res = await request(app).get('/trigger-error');
    expect(res.status).toBe(500);
    expect(res.body).toEqual({ error: 'INTERNAL_ERROR' });
    expect(res.body).not.toHaveProperty('stack');
    expect(res.body).not.toHaveProperty('message');
  });
});
